SELECT COUNT(DISTINCT seller_id) AS nb_vendeurs
FROM entrepot."sellers"
LIMIT 1000;

SELECT AVG(LENGTH(review_comment_message))::DOUBLE AS longueur_moyenne_commentaire
FROM entrepot."order_reviews"
WHERE review_comment_message IS NOT NULL AND review_comment_message <> '';

SELECT
    100.0 * SUM(CASE WHEN o.order_status = 'canceled' THEN 1 ELSE 0 END) / COUNT(*) AS taux_annulation
FROM entrepot."orders" AS o;

SELECT COUNT(DISTINCT customer_state) AS nb_etats
FROM entrepot."customers"
WHERE customer_state IS NOT NULL;
